const output = [];
for (const input of $input.all()) {
  const issue = $('Split Out').item.json;
  for (const history of issue.changelog?.histories ?? []) {
    (history.items ?? []).forEach((item, itemIndex) => {
      output.push({ json: {
        changelog_id: String(history.id), item_index: itemIndex,
        issue_key: issue.key, issue_id: String(issue.id),
        author_key: history.author?.key ?? history.author?.name ?? null,
        author_name: history.author?.displayName ?? null,
        created_at: history.created ?? null, field: item.field ?? null,
        fieldtype: item.fieldtype ?? null, from_value: item.from ?? null,
        from_string: item.fromString ?? null, to_value: item.to ?? null,
        to_string: item.toString ?? null
      }});
    });
  }
}
return output;

